// Writes the site URL from site.config.json into every place that needs an absolute URL:
// the canonical / Open Graph block in index.html, sitemap.xml and robots.txt.
// To switch domains: change "siteUrl" in site.config.json, then run `node scripts/apply-site-url.mjs`.
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const { siteUrl } = JSON.parse(readFileSync(new URL("site.config.json", root), "utf8"));
const base = siteUrl.replace(/\/$/, "");

const block = [
  "<!-- site-url:start (generated by scripts/apply-site-url.mjs from site.config.json — edit there) -->",
  `<link rel="canonical" href="${base}/">`,
  `<meta property="og:url" content="${base}/">`,
  `<meta property="og:image" content="${base}/img/og.jpg">`,
  "<!-- site-url:end -->",
].join("\n");

const indexUrl = new URL("index.html", root);
const html = readFileSync(indexUrl, "utf8");
const re = /<!-- site-url:start[\s\S]*?<!-- site-url:end -->/;
if (!re.test(html)) throw new Error("site-url markers not found in index.html");
writeFileSync(indexUrl, html.replace(re, block));

writeFileSync(new URL("sitemap.xml", root), `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url><loc>${base}/</loc></url>
</urlset>
`);
writeFileSync(new URL("robots.txt", root), `User-agent: *
Allow: /
Disallow: /lab.html

Sitemap: ${base}/sitemap.xml
`);
console.log(`Site URL set to ${base}`);
